UPDATE aiware.email_template
SET
  code = '"<!DOCTYPE html> <html xmlns=\"http://www.w3.org/1999/xhtml\"> <head> <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\"> <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"> <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"> <title></title> <link rel=\"stylesheet\" type=\"text/css\" href=\"https://fonts.googleapis.com/css?family=Nunito&display=swap\"> <style type=\"text/css\"> body { margin: 0; padding: 0; } .wrapper { max-width: 600px; width: 100%; margin: 0 auto; padding: 40px 35px; box-sizing: border-box; font-family: Nunito, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; } .card { padding: 10px 30px 30px 30px; border: 1px solid #D5DFE9; border-radius: 4px; } .btn { display: inline-block; margin: 0 auto; padding: 10px 28px; background: #4287f5; color: #fff; border-radius: 10px; font-weight: bold; text-decoration: none; } @media only screen and (max-width: 600px) { .wrapper { padding: 24px 16px !important; } .card { padding: 16px !important; } .btn { display: block !important; text-align: center !important; padding: 14px 20px !important; } .footer-text { display: block !important; margin: 0 0 4px 0 !important; } } </style> </head> <body> <div class=\"wrapper\"> <div style=\"min-height:60px; padding:40px 20px 20px 0px;\"> <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/> </div> <div class=\"card\"> <p style=\"font-size:16px; color:#2A323C\">You''re almost there! Please verify your email address to activate your Digital Media Hub free trial.</p> <a href=\"{{verify_url}}\" class=\"btn\">Verify Email</a> </div> <div style=\"text-align:center; margin-top:30px;\"> <span class=\"footer-text\" style=\"margin-right:5px; color:#5C6269\">© Veritone, Inc</span> <span class=\"footer-text\" style=\"color:#5C6269\">5291 California Ave | Ste. 350 | Irvine, CA 92617</span> </div> <div style=\"margin-top:8px; text-align:center;\"> <span style=\"margin-right:14px;\"><a style=\"color:#6098D1\" href=\"{{url_privacy_policy}}\">Privacy Policy</a></span> <span><a style=\"color:#6098D1\" href=\"{{url_term_service}}\">Term of Service</a></span> </div> </div> </body> </html>"'::jsonb,
  updated_date = NOW(),
  updated_by = '00000000-0000-0000-0000-000000000000'
WHERE email_template_id = 'trial-email-verification'
  AND organization_guid IS NULL;

UPDATE aiware.email_template
SET
  code = '"<!doctype html> <html xmlns=\"http://www.w3.org/1999/xhtml\"> <head> <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" /> <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" /> <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" /> <title></title> <link rel=\"stylesheet\" type=\"text/css\" href=\"https://fonts.googleapis.com/css2?family=Nunito:wght@400;700&display=swap\" /> <style type=\"text/css\"> body { margin: 0; padding: 0; } .wrapper { max-width: 600px; width: 100%; margin: 0 auto; padding: 40px 35px; box-sizing: border-box; font-family: Nunito, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif; } .hero { background: #212121; border-radius: 4px 4px 0 0; padding: 36px 32px; text-align: center; } .card { padding: 28px 32px 36px 32px; border: 1px solid #d5dfe9; border-top: none; border-radius: 0 0 4px 4px; background: #fff; } .card p { font-size: 15px; color: #4a5568; line-height: 1.7; } .card ol, .card ul { margin: 0 0 24px 0; padding-left: 22px; font-size: 15px; color: #4a5568; line-height: 1.7; } .card ul { list-style-type: disc; } .card li { margin-bottom: 10px; } .card li:last-child { margin-bottom: 0; } .btn { display: inline-block; padding: 11px 28px; background: #e3f730; color: #212121 !important; border-radius: 9999px; font-weight: bold; text-decoration: none; font-size: 15px; } @media only screen and (max-width: 600px) { .wrapper { padding: 16px !important; } .hero { padding: 24px 16px !important; border-radius: 4px 4px 0 0 !important; } .card { padding: 20px 16px 28px 16px !important; } .btn { display: block !important; text-align: center !important; padding: 14px 20px !important; box-sizing: border-box !important; } .footer-text { display: block !important; margin: 0 0 4px 0 !important; } } </style> </head> <body> <div class=\"wrapper\"> <div style=\"text-align: center; margin-top: 28px\"> <img src=\"https://static.veritone.com/logo/veritone-footer-banner-v1.png\" alt=\"Veritone\" style=\"max-width: 100%; width: auto; display: block; margin: 0 auto\" /> </div> <div class=\"hero\"> <h1 style=\" margin: 0 0 14px 0; font-size: 22px; font-weight: 800; color: #ffffff; letter-spacing: 0.4px; line-height: 1.3; \" > WELCOME TO YOUR DIGITAL MEDIA HUB </h1> <p style=\"font-size: 15px; color: #c8d4e8; line-height: 1.7\"> For the next 90 days, you''ll get a taste of what''s possible. </p> <p style=\"font-size: 15px; color: #c8d4e8; line-height: 1.7\"> Let''s automate the busywork together. </p> <a href=\"{{#if app_url}}{{app_url}}{{else}}https://us-1.veritone.com{{/if}}\" class=\"btn\" >Start Uploading</a > </div> <div class=\"card\"> {{#if first_name}} <p>Hi {{first_name}},</p> {{/if}} <p> Welcome aboard! Your 90-day free trial of Veritone Digital Media Hub is now active, including 5GB of storage to upload, process, store, and share your creative work. </p> <p> Trusted by some of the world''s most recognized brands, you''re in good hands. </p> <p> <span style=\"font-weight: bold\" >With your 90-day trial, you''ll get:</span > </p> <ul> <li>The ability to upload and store video, audio, and image files</li> <li> Powerful tools to help you search and find relevant content, fast </li> <li> Automatically generated tags and descriptions for all your content </li> <li>Access to features like Edit Metadata, Collections, and more</li> </ul> <p><span style=\"font-weight: bold\">Let''s get started</span></p> <ol> <li> <span style=\"font-weight: bold\">Sign in:</span> Log in to your account (make sure you''ve validated your email). </li> <li> <span style=\"font-weight: bold\">Upload your first file:</span> Easily add video, audio, and images. </li> <li> <span style=\"font-weight: bold\">Let us do the work:</span> We''ll automatically process your files and build searchable metadata. </li> </ol> <p> <span style=\"font-weight: bold\">A note about your trial:</span> We''ll send you a reminder before your trial ends so you''re never caught off guard. When your trial expires, you''ll need to either upgrade to a paid plan to retain access to your content, or download and export your files beforehand. Content that is not retained through a paid plan or downloaded and exported before your trial expires may be deleted after the trial ends. </p> <p> If you have any questions or want to learn more about paid plans, please reach out to <a href=\"mailto:{{#if support_email}}{{support_email}}{{else}}support@veritone.com{{/if}}\" style=\"color: #4287f5\" >{{#if support_email}}{{support_email}}{{else}}support@veritone.com{{/if}}</a > </p> <p style=\"margin-bottom: 0\"> Talk soon,<br /><span style=\"font-weight: bold\" >The Veritone Team</span > </p> </div> <div style=\"text-align: center; margin-top: 28px\"> <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" alt=\"Veritone\" style=\"max-width: 150px; width: auto; display: block; margin: 0 auto\" /> </div> <div style=\"text-align: center; margin-top: 16px\"> <span class=\"footer-text\" style=\"margin-right: 5px; color: #5c6269; font-size: 13px\" >© Veritone, Inc</span > <span class=\"footer-text\" style=\"color: #5c6269; font-size: 13px\" >5291 California Ave | Ste. 350 | Irvine, CA 92617</span > </div> <div style=\"margin-top: 8px; text-align: center\"> <span style=\"margin-right: 14px\" ><a style=\"color: #6098d1; font-size: 13px\" href=\"{{url_privacy_policy}}\" >Privacy Policy</a ></span > <span style=\"margin-right: 14px\" ><a style=\"color: #6098d1; font-size: 13px\" href=\"{{url_term_service}}\" >Term of Service</a ></span > <span ><a style=\"color: #6098d1; font-size: 13px\" href=\"{{#if url_support}}{{url_support}}{{else}}https://support.veritone.com/s/article/000005982?language=en_US{{/if}}\" >Support</a ></span > </div> </div> </body> </html>"'::jsonb,
  updated_date = NOW(),
  updated_by = '00000000-0000-0000-0000-000000000000'
WHERE email_template_id = 'trial-welcome'
  AND organization_guid IS NULL;

