  '"<!DOCTYPE html> <html xmlns=\"http://www.w3.org/1999/xhtml\"> <head> <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\"> <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"> <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"> <title></title> <link rel=\"stylesheet\" type=\"text/css\" href=\"https://fonts.googleapis.com/css?family=Nunito&display=swap\"> <style type=\"text/css\"> body { margin: 0; padding: 0; } .wrapper { max-width: 600px; width: 100%; margin: 0 auto; padding: 40px 35px; box-sizing: border-box; font-family: Nunito, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; } .card { padding: 10px 30px 30px 30px; border: 1px solid #D5DFE9; border-radius: 4px; } .btn { display: inline-block; margin: 0 auto; padding: 10px 28px; background: #4287f5; color: #fff; border-radius: 10px; font-weight: bold; text-decoration: none; } @media only screen and (max-width: 600px) { .wrapper { padding: 24px 16px !important; } .card { padding: 16px !important; text-align: left; } .btn { display: block !important; text-align: center !important; padding: 14px 20px !important; } .footer-text { display: block !important; margin: 0 0 4px 0 !important; } } </style> </head> <body> <div class=\"wrapper\"> <div style=\"min-height:60px; padding:40px 20px 20px 0px;\"> <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/> </div> <div class=\"card\"> <p style=\"font-size:16px; color:#2A323C\">Someone attempted to create a Digital Media Hub trial using this email address, but an account already exists and a new trial cannot be started.</p> <p style=\"font-size:16px; color:#2A323C\">If you made this request, you can sign in to your existing account below.</p> <div style=\"text-align:center; margin:28px 0;\"><a href=\"{{login_url}}\" class=\"btn\">Sign In</a></div> <p style=\"font-size:14px; color:#5C6269; margin-top:0;\">If you did not initiate this request, no action is needed. Your account and information are safe.</p> </div> <div style=\"text-align:center; margin-top:30px;\"> <span class=\"footer-text\" style=\"margin-right:5px; color:#5C6269\">© Veritone, Inc</span> <span class=\"footer-text\" style=\"color:#5C6269\">5291 California Ave | Ste. 350 | Irvine, CA 92617</span> </div> <div style=\"margin-top:8px; text-align:center;\"> <span style=\"margin-right:14px;\"><a style=\"color:#6098D1\" href=\"{{url_privacy_policy}}\">Privacy Policy</a></span> <span><a style=\"color:#6098D1\" href=\"{{url_term_service}}\">Term of Service</a></span> </div> </div> </body> </html>"'::jsonb,
  'Handlebars',
  '{}'::jsonb,
  'Veritone Team',
  'Your Digital Media Hub account',
  NOW(),
  NOW(),
  '00000000-0000-0000-0000-000000000000'
WHERE NOT EXISTS (
  SELECT 1 FROM aiware.email_template t
  WHERE t.email_template_id = 'trial-existing-account' AND t.organization_guid IS NULL
);
